import{d as c,C as t,o as u,c as g,j as a,a as o,E as s,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"道德经第五十九章","description":"依王弼农夫治田之喻读啬与早服，从重积德、有国之母读深根固柢。","frontmatter":{"title":"道德经第五十九章","description":"依王弼农夫治田之喻读啬与早服，从重积德、有国之母读深根固柢。","category":"guide","aliases":["道德经第五十九章","老子第五十九章","dao de jing chapter 59"],"source":["王弼《道德真经注》卷四"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-59.md","filePath":"daoism/dao-de-jing/chapter-59.md","lastUpdated":1794189804000}'),m={name:"daoism/dao-de-jing/chapter-59.md"},_=c({...m,setup(p){const n=[{id:"governing-and-husbanding",label:"治人事天，莫若啬",showLabel:!0,sentences:[["治人",{text:"事天",glossary:"shitian"},"，莫若",{text:"啬",glossary:"se"},"。"]],note:["【白话】治理人事、承事天命，没有比养护根本更合适的。这里的啬，依所据王注，借农夫治理田地来说明照护自然与去除妨害。","【王弼注择要】「啬，农夫。」注又说「全其自然，不急其荒病，除其所以荒病」，继而以「上承天命，下绥百姓」贯通治人事天。","【读法】啬常可循收敛、爱惜理解，本页明确采用所据农夫之喻。不急其荒病与除其所以荒病连读，着眼成因与养护，不把有害差异之外的一切多样性都当成必须去除之物。"]},{id:"early-return-and-accumulating",label:"早服谓之重积德",showLabel:!0,sentences:[["夫唯",{text:"啬",glossary:"se"},"，是谓",{text:"早服",glossary:"zaofu"},"。",{text:"早服",glossary:"zaofu"},"谓之",{text:"重积德",glossary:"chongjide"},"。"]],note:["【白话】正因为能这样养护根本，才叫作及早服从常道；能够早早归于常道，就叫作不断积累其德。经文把早服与积德相接，而非鼓励急求功效。","【王弼注择要】「唯重积德，不欲锐速，然后乃能使早服其常。」王弼由不求锐速解释早服，突出积累与服常的关联。","【读法】所据录文早服下注作早服常也，下文又说服其常；本站据后文释为及早服常。重在此按反复、层层积累读 chóng，与第二十六章厚重的 zhòng 分开。"]},{id:"capability-and-inexhaustibility",label:"重积德则无不克",showLabel:!0,sentences:[[{text:"重积德",glossary:"chongjide"},"则无不",{text:"克",glossary:"ke"},"。无不",{text:"克",glossary:"ke"},"则莫知其",{text:"极",glossary:"ji"},"。"]],note:["【白话】不断积累其德，便能无往而不能胜任、克服；能够如此，就看不出其作用的穷尽。经文用递进句势推展积德的效用。","【王弼注择要】莫知其极下注「道无穷也」。注把不见其极连到道的无穷，不只说一个人的能力难以估量。","【读法】克在此取能胜任、能克服义，极为穷尽。无不克是章内对德用的推极表达，不提供军事上征服一切或现实中永无失败的保证。"]},{id:"holding-a-country",label:"莫知其极，可以有国",showLabel:!0,sentences:[["莫知其",{text:"极",glossary:"ji"},"，可以",{text:"有国",glossary:"youguo"},"。"]],note:["【白话】作用不被有限的机巧与急求耗尽，才可以治理、持有国家。这里从德用不竭，转到能否安国。","【王弼注择要】「以有穷而莅国，非能有国也。」注从相反一面说，若凭有限而会穷尽的手段临国，就不能真正有国。","【读法】有国在此作一个整体词组，取保有、治理国家义，不套有形存在或据为己有的旧义。句子的重点是持久的根本，不只是一时取得政位。"]},{id:"the-root-of-a-country",label:"有国之母，可以长久",showLabel:!0,sentences:[[{text:"有国",glossary:"youguo"},"之",{text:"母",glossary:"mu"},"，可以长久。"]],note:["【白话】掌握使国家得以安定的根本，才可以长久。这里的母承接前面的积德，指安国之所由。","【王弼注择要】「国之所以安，谓之母。」紧接说「重积德是」，又说「唯图其根，然后营末，乃得其终也」，明确把积德与根本相连。","【读法】母在这里是安国之本，不专指母亲，也不直接照搬万物所由始的宇宙生成语境；字典据本章追加对应义项。"]},{id:"deep-roots-and-lasting-life",label:"深根固柢",showLabel:!0,sentences:[["是谓深根固",{text:"柢",glossary:"di"},"，长生",{text:"久视",glossary:"jiushi"},"之道。"]],note:["【白话】这就叫作使根扎深、使根柢坚固，是生命得以长久存续的道路。末句把治国与生命的持久，收束到先养其根的比喻中。","【读法】此句在所据录文未见单独逐句注，可承前注唯图其根、然后营末读。柢是根，久视在本页取长久生存，不按眼睛看得久直译。","【读法】本章论养根与长久，不据此承诺肉身不死；用于今日，可以检视行动是否持续耗损根本条件，具体健康问题仍须另据实际判断。"]}],r=[{id:"shitian",term:"事天",sense:1},{id:"se",term:"啬",sense:1},{id:"zaofu",term:"早服",sense:1},{id:"chongjide",term:"重积德",sense:1},{id:"ke",term:"克",sense:1},{id:"ji",term:"极",sense:1},{id:"youguo",term:"有国",sense:1},{id:"mu",term:"母",sense:2},{id:"di",term:"柢",sense:1},{id:"jiushi",term:"久视",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return u(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第五十九章",tabindex:"-1"},[o("道德经第五十九章 "),a("a",{class:"header-anchor",href:"#道德经第五十九章","aria-label":'Permalink to "道德经第五十九章"'},"​")],-1)),s(i,{title:"从农夫护田到深根固柢，怎样读啬与积德",summary:"本章用一连串承接句，从治人事天推到啬、早服、重积德，再落在有国与长久。王弼以农夫治田解释啬，以不欲锐速说明积德，以国之所以安解释母，重心在养根与持久。",points:[{label:"先读",text:"先看啬的所据注法：像农夫护田一样全其自然、去除使它荒病的条件。"},{label:"再辨",text:"早服连服其常读，重积德读 chóng jī dé，强调积累而不求锐速。"},{label:"后看",text:"无不克、有国与长久连在一起，最后以根柢作喻，不把它读成无限征服或不死承诺。"}],hint:"啬读 sè，重积德的重在本页读 chóng，柢读 dǐ。王弼此章啬农夫的解释，与收敛爱惜的常见训法分别说明。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[o("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),s(l,{sections:n,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[o("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),s(d,{lines:[{text:"治人事天，莫若啬。",tone:"先辨啬的注法",guide:"所据王注以农夫治田解释，重点在全自然、除荒病之因。"},{text:"早服谓之重积德。",tone:"积累与不欲锐速",guide:"早服依服其常读，积德使早服成为可能，不靠急求成效。"},{text:"有国之母，可以长久。",tone:"由安国之本到长久",guide:"母在这里指安国所由，王注明确联系重积德与先根后末。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[o("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(h,{items:r}),e[4]||(e[4]=b("",15))])}}});export{f as __pageData,_ as default};
